offer_mutation_rate_window_scope_ck.value:
(
      "offer_mutation_rate_window"."scope" = 'actor' and "offer_mutation_rate_window"."actor_id" is not null and "offer_mutation_rate_window"."attempts" between 1 and 120
    ) or (
      "offer_mutation_rate_window"."scope" = 'workspace' and "offer_mutation_rate_window"."actor_id" is null and "offer_mutation_rate_window"."attempts" between 1 and 1200
    )

offer_pdf_draft_error_ck.value:
(
      "offer_pdf_draft"."error_code" is null and "offer_pdf_draft"."error_retryable" is null
    ) or (
      "offer_pdf_draft"."error_code" ~ '^[a-z][a-z0-9_]{0,79}$' and "offer_pdf_draft"."error_retryable" is not null
    )

offer_release_candidate_error_ck.value:
(
      "offer_release_candidate"."error_code" is null and "offer_release_candidate"."error_retryable" is null
    ) or (
      "offer_release_candidate"."error_code" ~ '^[a-z][a-z0-9_]{0,79}$' and "offer_release_candidate"."error_retryable" is not null
    )

offer_issuance_error_ck.value:
(
      "offer_issuance"."error_code" is null and "offer_issuance"."error_retryable" is null
    ) or (
      "offer_issuance"."error_code" ~ '^[a-z][a-z0-9_]{0,79}$'
      and "offer_issuance"."error_retryable" is not null
    )
